function rpc(method,params={}){return new Promise((resolve,reject)=>{const id='frameforge-'+(++sequence),timer=setTimeout(()=>{pending.delete(id);reject(Error('The host did not respond. Inspect the saved request before retrying.'));},120000);pending.set(id,{resolve,reject,timer});window.parent.postMessage({jsonrpc:'2.0',id,method,params},'*');});}
function notify(method,params={}){window.parent.postMessage({jsonrpc:'2.0',method,params},'*');}
function unpack(result){if(result?.isError)throw Error(result.content?.[0]?.text??'Studio operation failed.');return result?.structuredContent??JSON.parse(result.content[0].text);}
async function tool(name,args={}){if(standalone)throw Error('Open the Frameforge plugin to connect this workspace.');return unpack(await rpc('tools/call',{name,arguments:args}));}
function status(message){$('#status').textContent=message;}
function safe(handler){return async(...args)=>{try{return await handler(...args);}catch(error){status(error.message);}};}
function writeRequired(){if(!connection.allowWrites)throw Error('This connection is read only. Enable local creation in its MCP settings to make changes.');}
function artwork(name){return typeof STUDIO_ART==='object'?STUDIO_ART[name]:'/explore-art/'+name;}
function recipeArt(w){return artwork(['qwen-edit','wan-camera','performance','motion-remix'].includes(w?.id)?'mcp-portrait.png':w?.explanation?.category==='image'?'mcp-product.png':'mcp-observatory.png');}
function download(name,text){const a=document.createElement('a');a.download=name;a.href='data:application/json;charset=utf-8,'+encodeURIComponent(text);a.textContent='Download '+name;document.body.append(a);a.click();a.remove();}
function stableRequest(key,payload){const signature=JSON.stringify(payload);let saved=requestMemory.get(key);try{saved??=JSON.parse(localStorage.getItem('frameforge-native-'+key)??'null');}catch{}if(saved?.signature===signature)return saved.id;const record={signature,id:crypto.randomUUID()};requestMemory.set(key,record);try{localStorage.setItem('frameforge-native-'+key,JSON.stringify(record));}catch{}return record.id;}
